mapper.select:
select  * from  Task_Push_Call_Record

1=1
    
        and  tpcrState=#{params.taskname}
    
    
        and  Tpcr_Create_Time=#{params.tpcrCreateTime}
    
    
        and  Tpcr_Create_Time>=#{params.tpcrCreateTimeStart}
    
    
        and   #{params.tpcrCreateTimeEnd}>= Tpcr_Create_Time
    
    
        and Te_Id = #{params.teId}
    

  
      
          order by ${params.sortFiled} ${params.sortType}
      
      
          order by ${params.sortSideFiled} ${params.sortType}
      
      
          order by Tpcr_Create_Time DESC
      
  
  limit #{params.start},#{params.size}

  select  count(1) from  Task_Push_Call_Record

    1=1
    
        and  tpcrState=#{params.taskname}
    
    
        and  Tpcr_Create_Time=#{params.tpcrCreateTime}
    
    
        and  Tpcr_Create_Time>=#{params.tpcrCreateTimeStart}
    
    
        and   #{params.tpcrCreateTimeEnd}>= Tpcr_Create_Time
    
    
        and Te_Id = #{params.teId}
